296	// Handles transformations based on the realization kind.
297	fn visit_kind_rules<'a>(
298	    s: &mut State<'a, '_, '_, '_>,
299	    content: &'a Content,
300	    styles: StyleChain<'a>,
301	) -> SourceResult<bool> {
302	    if let RealizationKind::Math = s.kind {
303	        // Transparently recurse into equations nested in math, so that things
304	        // like this work:
305	        // ```
306	        // #let my = $pi$
307	        // $ my r^2 $
308	        // ```
309	        if let Some(elem) = content.to_packed::<EquationElem>() {
310	            visit(s, &elem.body, styles)?;
311	            return Ok(true);
312	        }
313	
314	        // In normal realization, we apply regex show rules to consecutive
315	        // textual elements via `TEXTUAL` grouping. However, in math, this is
316	        // not desirable, so we just do it on a per-element basis.
317	        if let Some(elem) = content.to_packed::<SymbolElem>() {
318	            if let Some(m) = find_regex_match_in_str(elem.text.as_str(), styles) {
319	                visit_regex_match(s, &[(content, styles)], m)?;
320	                return Ok(true);
321	            }
322	        } else if let Some(elem) = content.to_packed::<TextElem>()
323	            && let Some(m) = find_regex_match_in_str(&elem.text, styles)
324	        {
325	            visit_regex_match(s, &[(content, styles)], m)?;
326	            return Ok(true);
327	        }
328	    } else {
329	        // Transparently wrap mathy content into equations.
330	        if content.can::<dyn Mathy>() && !content.is::<EquationElem>() {
331	            let eq = EquationElem::new(content.clone()).pack().spanned(content.span());
332	            visit(s, s.store(eq), styles)?;
333	            return Ok(true);
334	        }
335	
336	        // Symbols in non-math content transparently convert to `TextElem` so we
337	        // don't have to handle them in non-math layout.
338	        if let Some(elem) = content.to_packed::<SymbolElem>() {
339	            let mut text = TextElem::packed(elem.text.clone()).spanned(elem.span());
340	            if let Some(label) = elem.label() {
341	                text.set_label(label);
342	            }
343	            visit(s, s.store(text), styles)?;
344	            return Ok(true);
345	        }
346	    }
347	
348	    Ok(false)
349	}
