351	/// Tries to apply show rules to or prepare content. Returns `true` if the
352	/// element was handled.
353	fn visit_show_rules<'a>(
354	    s: &mut State<'a, '_, '_, '_>,
355	    content: &'a Content,
356	    styles: StyleChain<'a>,
357	) -> SourceResult<bool> {
358	    // Determines whether and how to proceed with show rule application.
359	    let Some(Verdict { prepared, mut map, step }) = verdict(s.engine, content, styles)
360	    else {
361	        return Ok(false);
362	    };
363	
364	    // Create a fresh copy that we can mutate.
365	    let mut output = Cow::Borrowed(content);
366	
367	    // If the element isn't yet prepared (we're seeing it for the first time),
368	    // prepare it.
369	    let mut tags = None;
370	    if !prepared {
371	        tags = prepare(s.engine, s.locator, output.to_mut(), &mut map, styles)?;
372	    }
373	
374	    // Apply a show rule step, if there is one.
375	    if let Some(step) = step {
376	        let chained = styles.chain(&map);
377	        let result = match step {
378	            // Apply a user-defined show rule.
379	            ShowStep::Recipe(recipe, guard) => {
380	                let context = Context::new(output.location(), Some(chained));
381	                recipe.apply(
382	                    s.engine,
383	                    context.track(),
384	                    output.into_owned().guarded(guard),
385	                )
386	            }
387	
388	            // Apply a built-in show rule.
389	            ShowStep::Builtin(rule) => {
390	                let _scope = typst_timing::TimingScope::new(output.elem().name());
391	                rule.apply(&output, s.engine, chained)
392	                    .map(|content| content.spanned(output.span()))
393	            }
394	        };
395	
396	        // Errors in show rules don't terminate compilation immediately. We just
397	        // continue with empty content for them and show all errors together, if
398	        // they remain by the end of the introspection loop.
399	        //
400	        // This way, we can ignore errors that only occur in earlier iterations
401	        // and also show more useful errors at once.
402	        output = Cow::Owned(s.engine.delay(result));
403	    }
404	
405	    // Lifetime-extend the realized content if necessary.
406	    let realized = match output {
407	        Cow::Borrowed(realized) => realized,
408	        Cow::Owned(realized) => s.store(realized),
409	    };
410	
411	    // Push start tag.
412	    let (start, end) = tags.unzip();
413	    if let Some(tag) = start {
414	        visit(s, s.store(TagElem::packed(tag)), styles)?;
415	    }
416	
417	    let prev_outside = s.outside;
418	    s.outside &= content.is::<ContextElem>();
419	    s.engine.route.increase();
420	    s.engine.route.check_show_depth().at(content.span())?;
421	
422	    visit_styled(s, realized, Cow::Owned(map), styles)?;
423	
424	    s.outside = prev_outside;
425	    s.engine.route.decrease();
426	
427	    // Push end tag.
428	    if let Some(tag) = end {
429	        visit(s, s.store(TagElem::packed(tag)), styles)?;
430	    }
431	
432	    Ok(true)
433	}
