435	/// Inspects an element and the current styles and determines how to proceed
436	/// with the styling.
437	fn verdict<'a>(
438	    engine: &mut Engine,
439	    elem: &'a Content,
440	    styles: StyleChain<'a>,
441	) -> Option<Verdict<'a>> {
442	    let prepared = elem.is_prepared();
443	    let mut map = Styles::new();
444	    let mut step = None;
445	
446	    // Do pre-synthesis on a cloned element to be able to match on synthesized
447	    // fields before real synthesis runs (during preparation). It's really
448	    // unfortunate that we have to do this, but otherwise
449	    // `show figure.where(kind: table)` won't work :(
450	    let mut elem = elem;
451	    let mut slot;
452	    if !prepared && elem.can::<dyn Synthesize>() {
453	        slot = elem.clone();
454	        slot.with_mut::<dyn Synthesize>()
455	            .unwrap()
456	            .synthesize(engine, styles)
457	            .ok();
458	        elem = &slot;
459	    }
460	
461	    // Lazily computes the total number of recipes in the style chain. We need
462	    // it to determine whether a particular show rule was already applied to the
463	    // `elem` previously. For this purpose, show rules are indexed from the
464	    // top of the chain as the chain might grow to the bottom.
465	    let depth = LazyCell::new(|| styles.recipes().count());
466	
467	    for (r, recipe) in styles.recipes().enumerate() {
468	        // We're not interested in recipes that don't match.
469	        if !recipe
470	            .selector()
471	            .is_some_and(|selector| selector.matches(elem, Some(styles)))
472	        {
473	            continue;
474	        }
475	
476	        // Special handling for show-set rules.
477	        if let Transformation::Style(transform) = recipe.transform() {
478	            if !prepared {
479	                map.apply(transform.clone());
480	            }
481	            continue;
482	        }
483	
484	        // If we already have a show step, don't look for one.
485	        if step.is_some() {
486	            continue;
487	        }
488	
489	        // Check whether this show rule was already applied to the element.
490	        let index = RecipeIndex(*depth - r);
491	        if elem.is_guarded(index) {
492	            continue;
493	        }
494	
495	        // We'll apply this recipe.
496	        step = Some(ShowStep::Recipe(recipe, index));
497	
498	        // If we found a show rule and are already prepared, there is nothing
499	        // else to do, so we can just break. If we are not yet prepared,
500	        // continue searching for potential show-set styles.
501	        if prepared {
502	            break;
503	        }
504	    }
505	
506	    // If we found no user-defined rule, also consider the built-in show rule.
507	    if step.is_none() {
508	        let target = styles.get(TargetElem::target);
509	        if let Some(rule) = engine.library.rules.get(target, elem) {
510	            step = Some(ShowStep::Builtin(rule));
511	        }
512	    }
513	
514	    // If there's no nothing to do, there is also no verdict.
515	    if step.is_none()
516	        && map.is_empty()
517	        && (prepared || {
518	            elem.label().is_none()
519	                && elem.location().is_none()
520	                && !elem.can::<dyn ShowSet>()
521	                && !elem.is_locatable()
522	                && !elem.is_tagged()
523	                && !elem.can::<dyn Synthesize>()
524	        })
525	    {
526	        return None;
527	    }
528	
529	    Some(Verdict { prepared, map, step })
530	}
