694	/// Tries to group the content in an active group or start a new one if any
695	/// grouping rule matches. Returns `true` if the element was grouped.
696	fn visit_grouping_rules<'a>(
697	    s: &mut State<'a, '_, '_, '_>,
698	    content: &'a Content,
699	    styles: StyleChain<'a>,
700	) -> SourceResult<bool> {
701	    let matching = s
702	        .rules
703	        .iter()
704	        .find(|&rule| (rule.effect)(content) == GroupingEffect::Trigger);
705	
706	    // Try to continue or finish an existing grouping.
707	    let mut i = 0;
708	    while let Some(active) = s.groupings.last_mut() {
709	        // Start a nested group if a rule with higher priority matches.
710	        if matching.is_some_and(|rule| rule.priority > active.rule.priority) {
711	            break;
712	        }
713	
714	        // If the element can be added to the active grouping, do it.
715	        let effect = (active.rule.effect)(content);
716	        if !active.interrupted && effect != GroupingEffect::Interrupt {
717	            active.contains_neutral |= effect == GroupingEffect::Neutral;
718	            s.sink.push((content, styles));
719	            return Ok(true);
720	        }
721	
722	        finish_innermost_grouping(s)?;
723	        i += 1;
724	        if i > 512 {
725	            // It seems like this case is only hit when there is a cycle between
726	            // a show rule and a grouping rule. The show rule produces content
727	            // that is matched by a grouping rule, which is then again processed
728	            // by the show rule, and so on. The two must be at an equilibrium,
729	            // otherwise either the "maximum show rule depth" or "maximum
730	            // grouping depth" errors are triggered.
731	            bail!(content.span(), "maximum grouping depth exceeded");
732	        }
733	    }
734	
735	    // Start a new grouping.
736	    if let Some(rule) = matching {
737	        let start = s.sink.len();
738	        s.groupings.push(Grouping {
739	            start,
740	            rule,
741	            interrupted: false,
742	            contains_neutral: false,
743	        });
744	        s.sink.push((content, styles));
745	        return Ok(true);
746	    }
747	
748	    Ok(false)
749	}
